        List<Integer> distinct = new ArrayList<>();
        for (int x : arr) if (!distinct.contains(x)) distinct.add(x);
        List<Integer> freqs = new ArrayList<>();
        for (int d : distinct) {
            int cnt = 0;
            for (int x : arr) if (x == d) cnt++;
            freqs.add(cnt);
        }
        for (int i = 0; i < freqs.size(); i++) {
            for (int j = i + 1; j < freqs.size(); j++) {
                if (freqs.get(i).equals(freqs.get(j))) return false;
            }
        }
        return true;
    }
}

