class Solution:
    def findUnsortedSubarray(self, nums: list[int]) -> int:
        n = len(nums)
        end, start = -1, -1
        max_val, min_val = nums[0], nums[n - 1]
        for i in range(1, n):
            max_val = max(max_val, nums[i])
            if nums[i] < max_val:
                end = i
        for i in range(n - 2, -1, -1):
            min_val = min(min_val, nums[i])
            if nums[i] > min_val:
                start = i
        return 0 if end == -1 else (end - start + 1)

